entries[430593] = { ["name"] = "Slumbering Soul Serum", ["text"] = "2 sec cast 2\nReagents:\nMycobloom (4), Blessing Blossom (5), Arathor's Spear (5), Gilded Vial (5)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\nUse: Elevate your focus to restore ( 207 * 10) mana over 10 sec, but you are defenseless until your focus is broken.\n71" }
entries[430594] = { ["name"] = "Draught of Silent Footfalls", ["text"] = "2 sec cast\nReagents:\nCrystalline Powder , Mycobloom (8), Luredrop (3), Orbinid (3), Gilded Vial (5)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\nUse: The imbiber gains invisibility for 12-18 sec (based on crafting quality). (5 Min Cooldown)\n71" }
entries[430595] = { ["name"] = "Draught of Shocking Revelations", ["text"] = "2 sec cast\nReagents:\nCrystalline Powder , Mycobloom (4), Orbinid (6), Arathor's Spear (2), Gilded Vial (5)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\nUse: Gain increased stealth detection. Every 1 sec, the light will attempt to smite a hidden foe within 20 yds.\n\nLasts for 15-25 sec (based on crafting quality).\n71" }
entries[430596] = { ["name"] = "Grotesque Vial", ["text"] = "2 sec cast\nReagents:\nWrithing Sample , Mycobloom (12), Luredrop (4), Arathor's Spear (4), Gilded Vial (5)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\nUse: While dead, twitch to spill a vial and dissolve yourself into a puddle of rejuvenating ooze. Up to 3 allies who step through you are healed for 2683 every 2 sec over 6 sec.\n\nShares a cooldown with healing potions.\n71" }
entries[430597] = { ["name"] = "Potion of Unwavering Focus", ["text"] = "2 sec cast\nReagents:\nCrystalline Powder , Mycobloom (12), Orbinid (4), Arathor's Spear (4), Gilded Vial (5)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\nUse: Fixate on the target enemy within 40 yds to increase your damage dealt to them by 2-4% (based on item quality). Lasts 20 sec.\n71" }
entries[430598] = { ["name"] = "Frontline Potion", ["text"] = "2 sec cast\nReagents:\nCrystalline Powder , Mycobloom (12), Blessing Blossom (4), Arathor's Spear (4), Gilded Vial (5)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\nUse: Consume to gain 10 armor and 2% maximum health for 6 sec. Whenever you are struck, gain an additional stack of these effects and increase the duration by 1 sec, up to 9 times. (500ms cooldown)\n71" }
entries[430599] = { ["name"] = "Tempered Potion", ["text"] = "2 sec cast\nReagents:\nWrithing Sample , Mycobloom (12), Luredrop (4), Arathor's Spear (4), Gilded Vial (5)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\nUse: Gain the effects of all inactive Tempered Flasks, increasing their associated secondary stats by 48 for 30 sec.\n71" }
entries[430600] = { ["name"] = "Potion of the Reborn Cheetah", ["text"] = "2 sec cast\nReagents:\nWrithing Sample , Mycobloom (12), Orbinid (4), Arathor's Spear (4), Gilded Vial (5)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\nUse: Drink to increase your movement speed by 60% for 12-20 sec (based on item quality). You will become dazed if struck.\n71" }
entries[430601] = { ["name"] = "Flask of Tempered Aggression", ["text"] = "2 sec cast 2\nReagents:\nNull Lotus , Viridescent Spores (2), Luredrop (12), Orbinid (12), Gilded Vial (2)\nOptional Reagents:\nDiscovery:\nExperimentation using relevant ingredients\n\nUse: Drink to increase your Critical Strike by 51 .\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour.\n71" }
