entries[430607] = { ["name"] = "Vicious Flask of Classical Spirits", ["text"] = "2 sec cast 2\nReagents:\nVicious Flask of Honor , Orbinid (6)\nVendor:\nHotharn\nZone:\nDornogal\nCost:\n7500\n\nUse: Drink to increase your mana regeneration by 8% whenever you have not cast a beneficial spell that costs mana for 5 sec.\n\nHonor gains increased by 15%.\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour.\n71" }
